from rich.table import Table

def test_explicit_highlight():
    table = Table(highlight=True)
    table.add_column(highlight=False)

    print(f"Column 0 highlight: {table.columns[0].highlight}")
    assert table.columns[0].highlight is False, "Column 0 should have highlight=False"

if __name__ == "__main__":
    try:
        test_explicit_highlight()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
